import React, { useState } from "react";
import { Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext"; // 👈 1. Import Auth Context
import LogoutButton from "./LogoutButton"; // 👈 2. Import Logout Button

const Menu = () => {
  const { user } = useAuth(); // 👈 3. Get user details
  const [selectedMenu, setSelectedMenu] = useState(0);
  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);

  // ... (Keep existing handleMenuClick logic)

  const handleProfileClick = () => {
    setIsProfileDropdownOpen(!isProfileDropdownOpen);
  };

  // 👈 4. Calculate initials safely (e.g., username "balaji" -> "BA")
  const userInitials = user ? user.slice(0, 2).toUpperCase() : "ZU";

  return (
    <div className="menu-container">
      {/* ... (Logo and Menu Links remain unchanged) ... */}

      <div
        className="profile"
        onClick={handleProfileClick}
        style={{ cursor: "pointer" }}
      >
        {/* 👈 5. Real user initials and username display */}
        <div className="avatar">{userInitials}</div>
        <p className="username">{user || "USERID"}</p>
      </div>

      {/* 👈 6. Hidden Profile Logout Overlay Layer */}
      {isProfileDropdownOpen && (
        <div style={styles.dropdownBox}>
          <div style={styles.dropdownUserHeader}>
            <strong>{user}</strong>
          </div>
          <hr style={{ border: "0.5px solid #eee", margin: "8px 0" }} />
          <LogoutButton />
        </div>
      )}
    </div>
  );
};

// ... (Add necessary minimal styling for dropdownBox and dropdownUserHeader to avoid breaking layout) ...
export default Menu;
